SELECT result_id
FROM doc_results
WHERE survey_id = #{surveyId}
AND status = '0'

    AND commit_time BETWEEN #{startTime} AND #{endTime}


    AND commit_time >= #{startTime}


    AND commit_time <= #{endTime}

