#{resultId}
AND question_id = #{questionId} GROUP BY answer_value

SELECT TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(a.answer_value, ',', n.n), ',', -1)) as optionValue, COUNT(*) as count FROM doc_answers a JOIN ( SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 ) n ON CHAR_LENGTH(a.answer_value) - CHAR_LENGTH(REPLACE(a.answer_value, ',', '')) >= n.n - 1 WHERE a.result_id IN
#{resultId}
AND a.question_id = #{questionId} GROUP BY TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(a.answer_value, ',', n.n), ',', -1))

